mapper.select:
SELECT p.*, u.name AS createdByName, u.class_num AS classNum
FROM tbl_posts p
JOIN tbl_users u ON p.user_id = u.user_id
WHERE p.category = #{category}
ORDER BY p.post_id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE tbl_posts
SET title = #{title},
content = #{content},
category = #{category}
WHERE post_id = #{postId}

mapper.select:
SELECT c.comment_id, c.post_id, c.user_id, u.name AS createdByName, u.class_num AS classNum, c.content, c.created_at
FROM tbl_comments c
JOIN tbl_users u ON c.user_id = u.user_id
WHERE c.post_id = #{postId}
ORDER BY c.created_at DESC;

mapper.update:
UPDATE tbl_comments
SET content = #{content}
WHERE comment_id = #{commentId}
